import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFont = makeLoadFont('Inter');

// Load font at module level to guarantee it's ready before frame 0
const { fontFamily } = loadFont();



export type SequentialListProps = Record<string, any>;

const SequentialList: React.FC<SequentialListProps> = ({
  backgroundColor = "#0f172a",
  transparentBackground = false,
  durationInSeconds = 12,
  step1Text = "What's happening?",
  step2Text = "How you got here?",
  step3Text = "What's at risk?",
  step4Text = "What should we do?",
  textColor = "#f8fafc",
  accentColor = "#22d3ee",
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Handle transparency logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  const items = [
    { text: step1Text, isAccent: false },
    { text: step2Text, isAccent: false },
    { text: step3Text, isAccent: false },
    { text: step4Text, isAccent: true },
  ];

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily,
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "flex-start",
          gap: "64px",
        }}
      >
        {items.map((item, index) => {
          // Stagger each item by 45 frames (1.5 seconds at 30fps)
          const delay = 15 + index * 45;
          
          const entranceSpring = spring({
            frame: frame - delay,
            fps,
            config: { damping: 14, mass: 1, stiffness: 100 },
          });

          const opacity = interpolate(entranceSpring, [0, 1], [0, 1], {
            extrapolateRight: "clamp",
          });
          
          const translateY = interpolate(entranceSpring, [0, 1], [40, 0]);

          // Continuous subtle pulse for the accent item, starting after the entrance finishes
          const pulseScale = item.isAccent
            ? 1 + Math.sin(Math.max(0, frame - delay - 45) * 0.1) * 0.02
            : 1;

          // Combine the entrance spring scale with the continuous pulse
          const scale = entranceSpring * pulseScale;

          return (
            <div
              key={index}
              style={{
                display: "flex",
                flexDirection: "row",
                alignItems: "center",
                opacity,
                transform: `translateY(${translateY}px) scale(${scale})`,
                transformOrigin: "left center",
                transition: "none",
              }}
            >
              <div
                style={{
                  width: "80px",
                  height: "80px",
                  borderRadius: "40px",
                  backgroundColor: item.isAccent
                    ? accentColor
                    : "rgba(255, 255, 255, 0.08)",
                  color: item.isAccent ? "#0f172a" : textColor,
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                  fontSize: "36px",
                  fontWeight: 800,
                  marginRight: "40px",
                  boxShadow: item.isAccent
                    ? `0 0 30px ${accentColor}60`
                    : "none",
                  transition: "none",
                }}
              >
                {index + 1}
              </div>
              <div
                style={{
                  fontSize: "56px",
                  color: item.isAccent ? accentColor : textColor,
                  fontWeight: item.isAccent ? 700 : 500,
                  letterSpacing: "-0.02em",
                  transition: "none",
                }}
              >
                {item.text}
              </div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default SequentialList;